// storageEnvelopeVectors is testdata/storage_envelope_v1.json, a copy of the
// vgi extension's test/vectors/storage_envelope_v1.json (generated by
// vgi-python's scripts/gen_storage_envelope_vectors.py). Every SDK checks its
// envelope against these bytes.
type storageEnvelopeVectors struct {
	Format            string `json:"format"`
	TagInline         int    `json:"tag_inline"`
	TagPointer        int    `json:"tag_pointer"`
	PointerFixedBytes int    `json:"pointer_fixed_bytes"`
	DefaultBytes      int    `json:"default_externalize_bytes"`
	Inline            []struct {
		Name     string `json:"name"`
		Value    string `json:"value_hex"`
		Envelope string `json:"envelope_hex"`
	} `json:"inline"`
	Pointers []struct {
		Name     string `json:"name"`
		ObjectID string `json:"object_id"`
		Size     int64  `json:"size"`
		SHA256   string `json:"sha256"`
		Envelope string `json:"envelope_hex"`
	} `json:"pointers"`
	Malformed []struct {
		Name     string `json:"name"`
		Envelope string `json:"envelope_hex"`
		Error    string `json:"error"`
	} `json:"malformed"`
	ScopeExecutionIDs struct {
		Cases []struct {
			Kind        string `json:"kind"`
			Ident       string `json:"ident_hex"`
			ExecutionID string `json:"execution_id"`
		} `json:"cases"`
	} `json:"scope_execution_ids"`
	ScopeShards struct {
		Cases []struct {
			ShardKey string `json:"shard_key"`
			Shard    string `json:"shard"`
		} `json:"cases"`
	} `json:"scope_shards"`
}

const storageEnvelopeVectorsPath = "testdata/storage_envelope_v1.json"

func loadStorageEnvelopeVectors(t *testing.T) storageEnvelopeVectors {
	t.Helper()
	raw, err := os.ReadFile(storageEnvelopeVectorsPath)
	if err != nil {
		t.Fatal(err)
	}
	var v storageEnvelopeVectors
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatal(err)
	}
	if v.Format != "vgi.storage_envelope.v1" {
		t.Fatalf("format = %q", v.Format)
	}
	return v
}

// TestStorageEnvelopeVectorsMatchExtension checks this copy against the vgi
// extension's when a checkout is at VGI_SRC (the integration lanes set it) or
// beside this repository.
func TestStorageEnvelopeVectorsMatchExtension(t *testing.T) {
	src := os.Getenv("VGI_SRC")
	if src == "" {
		src = filepath.Join("..", "..", "vgi")
	}
	upstream, err := os.ReadFile(filepath.Join(src, "test", "vectors", "storage_envelope_v1.json"))
	if err != nil {
		t.Skipf("no vgi extension checkout at %s", src)
	}
	ours, err := os.ReadFile(storageEnvelopeVectorsPath)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(ours, upstream) {
		t.Fatalf("%s differs from %s/test/vectors/storage_envelope_v1.json; copy it over", storageEnvelopeVectorsPath, src)
	}
}

func TestStorageEnvelopeVectors(t *testing.T) {
	v := loadStorageEnvelopeVectors(t)
	if v.TagInline != int(envelopeTagInline) || v.TagPointer != int(envelopeTagPointer) || v.PointerFixedBytes != envelopePointerFixed {
		t.Fatalf("constants differ: %+v", v)
	}
	if v.DefaultBytes != DefaultStorageExternalizeBytes {
		t.Fatalf("default threshold %d, vectors say %d", DefaultStorageExternalizeBytes, v.DefaultBytes)
	}
	s, err := NewExternalizingStorage(nil, nil, 4096, 0)
	if err != nil {
		t.Fatal(err)
	}
	for _, c := range v.Inline {
		value, envelope := mustHex(t, c.Value), mustHex(t, c.Envelope)
		if got := EncodeStorageInline(value); !bytes.Equal(got, envelope) {
			t.Errorf("%s: encode = %x, want %x", c.Name, got, envelope)
		}
		got, err := s.decodeOne(envelope, nil)
		if err != nil || !bytes.Equal(got, value) || got == nil {
			t.Errorf("%s: decode = %x, %v", c.Name, got, err)
		}
	}
	for _, c := range v.Pointers {
		envelope := mustHex(t, c.Envelope)
		ref := vgirpc.BlobRef{ObjectID: c.ObjectID, Size: c.Size, SHA256: c.SHA256}
		got, err := EncodeStoragePointer(ref)
		if err != nil || !bytes.Equal(got, envelope) {
			t.Errorf("%s: encode = %x, %v; want %x", c.Name, got, err, envelope)
		}
		back, err := DecodeStoragePointer(envelope)
		if err != nil || back != ref {
			t.Errorf("%s: decode = %+v, %v", c.Name, back, err)
		}
		// A pointer read with no vendor configured is an error, not bytes.
		var envErr *StorageEnvelopeError
		if _, err := s.decodeOne(envelope, nil); !errors.As(err, &envErr) {
			t.Errorf("%s: pointer without a vendor: %v", c.Name, err)
		}
	}
	for _, c := range v.Malformed {
		var envErr *StorageEnvelopeError
		if _, err := s.decodeValues([][]byte{mustHex(t, c.Envelope)}, nil); !errors.As(err, &envErr) {
			t.Errorf("%s (%s): decode error = %v", c.Name, c.Error, err)
		}
	}
	for _, c := range v.ScopeExecutionIDs.Cases {
		if got := blobExecutionID(c.Kind, mustHex(t, c.Ident)); got != c.ExecutionID {
			t.Errorf("blobExecutionID(%s, %s) = %q, want %q", c.Kind, c.Ident, got, c.ExecutionID)
		}
	}
	for _, c := range v.ScopeShards.Cases {
		if got := blobShard(c.ShardKey); got != c.Shard {
			t.Errorf("blobShard(%q) = %q, want %q", c.ShardKey, got, c.Shard)
		}
	}
}

func TestStorageBlobErrorContract(t *testing.T) {
	ref := vgirpc.BlobRef{ObjectID: "0123456789abcdef0123456789abcdef", Size: 10, SHA256: "00"}
	cases := []struct {
		err  error
		kind StorageBlobErrorKind
		want string
	}{
		{&vgirpc.VendorError{Code: vgirpc.VendorCodeSHA256Mismatch}, StorageBlobIntegrity,
			"storage blob 0123456789abcdef0123456789abcdef failed its integrity check: sha256 mismatch"},
		{&vgirpc.VendorError{Code: vgirpc.VendorCodeSizeMismatch}, StorageBlobIntegrity,
			"storage blob 0123456789abcdef0123456789abcdef failed its integrity check: size mismatch (expected 10 bytes)"},
		{&vgirpc.VendorError{Status: 404, Code: "not_found"}, StorageBlobMissing,
			"storage blob 0123456789abcdef0123456789abcdef is missing: not found in the blob vendor (expired or deleted?)"},
		{&vgirpc.VendorError{Status: 404, Code: "NoSuchKey"}, StorageBlobMissing, ""},
		{&vgirpc.VendorError{Status: 404, Code: "not_uploaded"}, StorageBlobMissing, ""},
		{&vgirpc.VendorError{Message: "boom", Status: 500}, StorageBlobUnreadable,
			"storage blob 0123456789abcdef0123456789abcdef could not be read: boom"},
	}
	for _, c := range cases {
		err := blobReadError(ref, c.err)
		var be *StorageBlobError
		if !errors.As(err, &be) || be.Kind != c.kind || (c.want != "" && err.Error() != c.want) {
			t.Errorf("%v -> %v (kind %v)", c.err, err, be)
		}
	}
}

func TestExternalizingStorageThresholdValidation(t *testing.T) {
	if _, err := NewExternalizingStorage(nil, nil, 0, 0); err == nil {
		t.Error("threshold 0 accepted")
	}
	if _, err := NewExternalizingStorage(nil, nil, 2<<20, 1<<20); err == nil {
		t.Error("threshold above the backend cap accepted")
	}
}
